  ('ict-lec-ch04-mcq-312', 'class9-ict-bn-guide', 'ict-lecture-satt', 'সৌমিত্রকে তার শখের কাজে কোন করতে কোনটি ব্যবহার করা হয়? সফটওয়্যার ব্যবহার করতে হয়?', 'mcq', '{"ক":"wbD","খ":"I‡cb","গ":"স্প্রেডশিট","ঘ":"†mBf GR"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 4, false),
