  ('ict-lec-ch04-mcq-875', 'class9-ict-bn-guide', 'ict-lecture-satt', 'উক্ত কাজের জন্য রাজন ব্যবহার করতে পারবে ii. Awd‡mi wnmve i. = A1  B2 ii. =A1 * B1', 'mcq', '{"ক":"N নিচের ওয়াকর্ শিটটি লক্ষ করে ২৮৯ ও ২৯০ bs cÖ‡kœi","খ":"iii I I A B C D","গ":"ii iii","ঘ":"Rent উপস্থাপন করা অধিক সুবিধাজনক। কারণ এখানে 2 Nila 12000"}'::jsonb, 'ক', null, 1, null, 'mcq_bank', null, 4, false),
  ('ict-lec-ch04-mcq-881', 'class9-ict-bn-guide', 'ict-lecture-satt', 'C(?) চিহ্ন তে কত টাকা হবে? (cÖ‡qvM) সে তার কম্পিউটার চালু করে স্প্রেডশিটেA1 †mj Ges', 'mcq', '{"ক":"50","খ":"60","গ":"70","ঘ":"80"}'::jsonb, 'খ', null, 1, null, 'mcq_bank', null, 4, false),
